const money=x=>new Intl.NumberFormat('zh-TW',{style:'currency',currency:s.currency,maximumFractionDigits:0}).format(x),num=(x,d=2)=>x==null?'資料不足':(Number(x.toFixed(d))===0?0:x).toLocaleString('zh-TW',{maximumFractionDigits:d,minimumFractionDigits:d}),date=x=>new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(x));
