function saveStatus(message){saveMessage=message;$('save-status').textContent=message;}
function persist(replace=false){try{reconcileReveal(s,state,globalThis.localStorage);if(!store)throw Error('此瀏覽器無法使用本機保存，請匯出 JSON 備份');store.write(makeSave(s,state,s.datasetVersion,draft(),createdAt),{replace});activePractice=true;practiceMeta=JSON.parse(store.raw()).practice;saveBlocked=false;saveStatus('已自動保存於此瀏覽器 · '+new Date().toLocaleTimeString('zh-TW'));return true;}catch(e){saveStatus(/quota|security|storage/i.test(e.message)?'本機保存失敗（空間不足或瀏覽器限制）；請立即匯出 JSON 備份':e.message);return false;}}
function download(text,type,filename){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function syncSettings(){renderIndicatorFields();if(identityVisible(s,state))$('start-year').innerHTML='<option value="all">全部可選年份</option>'+[...new Set(newDataset().scenarioData.bars.map(b=>b.date.slice(0,4)))].map(y=>`<option value="${y}">${y}</option>`).join('');$('length').value=String(s.length);$('seed').value=s.seed;$('start-year').value=identityVisible()?s.startYear:'all';startOptions();$('start-date').value=identityVisible()?(s.requestedStartDate??''):'';}
function startOptions(){if(!identityVisible(s,state)){$('start-date').innerHTML='<option value="">盲測自動選取</option>';$('start-year').innerHTML='<option value="all">全部資料範圍（日期隱藏）</option>';return;}const previous=$('start-date').value;$('start-date').innerHTML='<option value="">自動選取連續區段</option>'+eligibleStarts(newDataset().scenarioData,Number($('length').value),s.warmup===40?40:260,$('start-year').value).map(d=>`<option value="${d}">${d}</option>`).join('');if([...$('start-date').options].some(x=>x.value===previous))$('start-date').value=previous;}
function costSummary(){const c=modelFor(s);if(c.version==='legacy-0.1%-no-tax')return '買賣手續費各0.1%；未計證交稅';if(c.version==='tw-legacy-tax-v1')return `買賣手續費各0.1%；賣出證交稅 ${ratePercent(c.sellTaxRate)}%。手續費不取整，證交稅整元捨去。`;if(c.version==='tw-etf-v1')return `本局 ETF 費用設定：雙向手續費 ${ratePercent(c.feeRate)}%，最低 ${feeMoney(c.minimumCommission)}；賣出證交稅 0.1%。`;return `台灣${c.instrumentType==='stock'?'個股（一般非當沖）':'股票型ETF'}費稅簡化模型：手續費基準 0.1425% × ${num(c.discount*100,2)}%＝${ratePercent(c.feeRate)}%，最低 ${feeMoney(c.minimumCommission)}；僅賣出證交稅 ${ratePercent(c.sellTaxRate)}%。費稅整元捨去，手續費再套最低費，整局固定。`;}
