function showNewCostPreview(){try{const c=newCostModel();$('new-cost-warning').textContent=`目前資料類型：${c.assetClass==='stock'?'個股':'股票型ETF'}。新局有效手續費 ${ratePercent(c.feeRate)}%，最低 ${feeMoney(c.minimumCommission)}；賣出稅 ${ratePercent(c.sellTaxRate)}%，買入不課證交稅。`;}catch(e){$('new-cost-warning').textContent=e.message;}}

