function openIndicatorEditor(group,id=null){if(!Object.hasOwn(indicatorNames,group))return;if(['sma','ema'].includes(group)){const lines=movingAverageInstances(s.indicatorSettings);if(!id&&lines.length>=8){$('indicator-error').textContent='均線最多 8 條，請先移除一條。';return;}pendingMA=id?lines.find(l=>l.id===id):newMA(group);if(!pendingMA)return;editorId=pendingMA.id;}else{editorId=null;pendingMA=null;}editorGroup=group;$('indicator-feedback').textContent='';$('indicator-menu').hidden=true;$('open-indicators').setAttribute?.('aria-expanded','false');$('indicator-error').textContent='';renderIndicatorFields();$('indicator-editor-title').focus?.();$('indicator-editor').scrollIntoView?.({block:'nearest',behavior:'smooth'});}

function indicatorPanels(study,bars){const cfg=s.indicatorSettings,groups=[['RSI',['rsi'],cfg.rsiEnabled],['MACD / 訊號 / 柱值',['macd','macdSignal','macdHistogram'],cfg.macdEnabled],['KD',['k','d'],cfg.kdEnabled],['換算後成交量均線',['volumeMA'],cfg.volumeMAEnabled]];return groups.filter(g=>g[2]).map(([label,keys])=>{const lines=keys.map(k=>study.series[k].slice(-bars.length)),values=lines.flat().filter(Number.isFinite),floor=label==='RSI'||label==='KD'?0:Math.min(0,...values),ceiling=label==='RSI'||label==='KD'?100:Math.max(1,...values),y=v=>104-(v-floor)/(ceiling-floor)*76,x=i=>45+(583/bars.length)*(i+.5);return `<svg class="indicator-panel" viewBox="0 0 640 120" role="img" aria-label="${label}，僅已完成交易日"><text x="10" y="15" fill="#a6b4c8" font-size="11">${label}${values.length?'':' · 資料不足'}</text><text x="0" y="35" fill="#8ca1bc" font-size="9">${num(ceiling,1)}</text><text x="0" y="106" fill="#8ca1bc" font-size="9">${num(floor,1)}</text><line x1="45" y1="104" x2="628" y2="104" stroke="#29394e"/>${lines.map((line,j)=>`<polyline points="${line.map((v,i)=>v==null?null:`${x(i)},${y(v)}`).filter(Boolean).join(' ')}" fill="none" stroke="${['#e0ba71','#79aaff','#be8af0'][j]}" stroke-width="1.5"/>`).join('')}</svg>`;}).join('');}
$('indicator-form').addEventListener('submit',e=>{e.preventDefault();if(!editorGroup)return;try{const form=new FormData(e.target),cfg={...s.indicatorSettings};if(['sma','ema'].includes(editorGroup)){const lines=movingAverageInstances(cfg),line={...pendingMA,period:Number(form.get(editorGroup+'Period')),color:form.get('maColor')||pendingMA.color},index=lines.findIndex(l=>l.id===editorId);if(index<0)lines.push(line);else lines[index]=line;cfg.movingAverages=lines;pendingMA=line;}else{for(const k of Object.keys(cfg).filter(k=>k.startsWith(editorGroup)&&!k.endsWith('Enabled')))cfg[k]=Number(form.get(k));cfg[editorGroup+'Enabled']=true;}setIndicatorSettings(s,state,normalizeIndicatorSettings(cfg));$('indicator-error').textContent=`已保存，自第 ${state.journal.length+1} 筆決策生效${state.finished?'（僅供回顧）':''}`;render();persist();}catch(err){$('indicator-error').textContent=err.message;}});
function removeSelectedIndicator(group,id=null){
 if(!Object.hasOwn(indicatorNames,group))return;
 const cfg={...s.indicatorSettings},lines=movingAverageInstances(cfg),line=lines.find(l=>l.id===id);
 if(['sma','ema'].includes(group)){if(!line)return;cfg.movingAverages=lines.filter(l=>l.id!==id);}else{if(!cfg[group+'Enabled'])return;cfg[group+'Enabled']=false;}
 const name=line?`${line.type.toUpperCase()} ${line.period} · 線 ${lines.indexOf(line)+1}`:indicatorNames[group];
 setIndicatorSettings(s,state,cfg);editorGroup=null;editorId=null;pendingMA=null;render();persist();
 $('indicator-feedback').textContent=`已移除 ${name}。只調整圖表，交易紀錄不變。`;$('open-indicators').focus?.();
}
$('remove-indicator').addEventListener('click',()=>{if(editorGroup)removeSelectedIndicator(editorGroup,editorId);});

function closeIndicatorEditor(){const group=editorGroup,id=editorId;editorGroup=null;editorId=null;pendingMA=null;$('indicator-editor').hidden=true;const chip=group?$('indicator-chips').querySelector?.(id?'[data-instance="'+id+'"]':'[data-indicator="'+group+'"]'):null;(chip??$('open-indicators')).focus?.();}
$('close-indicator').addEventListener('click',closeIndicatorEditor);
for(const id of ['indicator-chips','indicator-options'])$(id).addEventListener('click',e=>{const target=e.target.closest?.('[data-indicator], [data-preset], [data-remove-indicator]');if(target?.dataset.removeIndicator){removeSelectedIndicator(target.dataset.removeIndicator,target.dataset.instance??null);return;}if(target?.dataset.preset){const lines=movingAverageInstances(s.indicatorSettings),periods=target.dataset.preset.split(',').map(Number);if(lines.length+periods.length>8)return;setIndicatorSettings(s,state,{...s.indicatorSettings,movingAverages:[...lines,...periods.map((period,i)=>newMA('sma',period,lines.length+i))]});$('indicator-menu').hidden=true;$('open-indicators').setAttribute?.('aria-expanded','false');render();persist();$('indicator-feedback').textContent='已加入 SMA '+periods.join(' / ')+'。點名稱可設定，點移除可取消選用。';$('open-indicators').focus?.();return;}const group=target?.dataset.indicator;if(group)openIndicatorEditor(group,target.dataset.instance??null);});

function showView(view,scroll=true){if(!activePractice&&['trade','report'].includes(view))view='records';activeView=view;$('view-records').hidden=view!=='records';if(view==='records')renderPractices();for(const name of ['setup','trade','report']){$('view-'+name).hidden=name!==view;$('tab-'+name).setAttribute?.('aria-current',name===view?'step':'false');}if(document.body)document.body.dataset.view=view;if(scroll)globalThis.scrollTo?.({top:0,behavior:'instant'});}
function refreshWorkspace(){
 $('start-summary').textContent=`${s.length} 個決策日 · 初始資金 ${money(s.initialCash)} · 本機自動保存`;
 $('enter-trade').textContent=!activePractice?'建立新的練習 →':state.finished?'查看已完成回合 →':state.journal.length?`繼續第 ${state.index+1} / ${s.length} 日練習 →`:'開始這段練習 →';
 $('report-progress').textContent=state.finished?'回合已完成。整理你的判斷，再下載交易練習報告。':`已完成 ${state.journal.length} / ${s.length} 次決策。可先整理筆記與匯出階段報告。`;
 $('blind-status-mini').textContent=identityVisible(s,state)?'目前顯示身分':s.blind?.everRevealed||s.blind?.legacy?'曾查看背景資訊 · 畫面隱藏身分':'盲測 · 標的與日期隱藏';
 const j=state.journal.at(-1);$('last-result').hidden=!j;if(j)$('last-result').textContent=j.status==='cancelled'?'上一筆未成交：開盤成交與費稅超出可用現金；整筆取消，未收費稅，已前進一天。':j.side==='hold'?'上一日選擇觀望，已揭露新行情。':`上一筆${labels[j.side]} ${j.quantity} 單位，成交 ${num(j.price)}，${costBreakdown({fee:j.fee,tax:j.tax??0,totalCost:j.totalCost??j.fee})}。`;
}
for(const name of ['setup','trade','report'])$('tab-'+name).addEventListener('click',()=>showView(name));
$('enter-trade').addEventListener('click',()=>{if(!activePractice)setup(false);else showView(state.finished?'report':'trade');});
$('return-trade').addEventListener('click',()=>showView('trade'));
$('open-indicators').addEventListener('click',()=>{const menu=$('indicator-menu');menu.hidden=!menu.hidden;$('open-indicators').setAttribute?.('aria-expanded',String(!menu.hidden));editorGroup=null;$('indicator-editor').hidden=true;if(!menu.hidden)menu.querySelector?.('button:not([disabled])')?.focus();});
for(const id of ['mobile-trade-link','inline-trade-link'])$(id).addEventListener('click',()=>{if(state.finished)showView('report');});
document.querySelector?.('#complete a')?.addEventListener('click',()=>showView('report'));

$('indicator-menu').addEventListener('keydown',e=>{if(e.key==='Escape'){$('indicator-menu').hidden=true;$('open-indicators').setAttribute?.('aria-expanded','false');$('open-indicators').focus?.();}});
$('indicator-editor').addEventListener('keydown',e=>{if(e.key==='Escape')closeIndicatorEditor();});

