function loadPractice(raw){const loaded=registry.restore(raw);uiIdentityShown=false;$('indicator-feedback').textContent='';s=loaded.s;data=registry.get(s.datasetVersion).scenarioData;state=loaded.state;createdAt=loaded.createdAt;practiceMeta=JSON.parse(raw).practice;activePractice=true;saveBlocked=false;editorGroup=null;editorId=null;$('indicator-menu').hidden=true;applyDraft(loaded.draft);try{reconcileReveal(s,state,globalThis.localStorage);}catch(e){saveStatus(e.message);}syncSettings();render();saveStatus('已載入「'+practiceMeta.name+'」');}
function renderPractices(){try{const rows=store?.list({deleted:showDeleted})??[];$('records-list').innerHTML=rows.length?rows.map(r=>{const missing=registry.status(r.save)==='unavailable',j=r.save.state?.journal??[],done=r.save.state?.finished;return `<article class="practice-row"><div><h2>${esc(r.name)}</h2><p>${missing?'所需歷史資料暫時無法使用，仍可下載備份':done?'已完成':'進行中'} · 已決策 ${j.length} / ${r.save.scenario?.length??'?'} 日${r.id===practiceMeta?.id&&activePractice?' · 目前開啟':''}</p></div><div class="practice-actions">${showDeleted?`<button data-practice-action="restore" data-id="${esc(r.id)}">還原</button>`:`<button class="primary" data-practice-action="open" ${missing?'disabled':''} data-id="${esc(r.id)}">${done?'查看報告':'繼續練習'}</button><button data-practice-action="rename" data-id="${esc(r.id)}">命名</button><button data-practice-action="json" data-id="${esc(r.id)}">備份 JSON</button><button data-practice-action="pdf" ${missing?'disabled':''} data-id="${esc(r.id)}">下載 PDF</button><button data-practice-action="trash" data-id="${esc(r.id)}">移至已刪除</button>`}</div></article>`}).join(''):`<div class="empty">${showDeleted?'沒有已刪除的練習。':'尚無練習，請到準備回合開始。'}</div>`;$('records-toggle').textContent=showDeleted?'返回練習清單':'查看已刪除';$('records-error').textContent='';}catch(e){$('records-error').textContent=e.message;}}
$('recalculate-tax').addEventListener('click',()=>{
 const button=$('recalculate-tax');button.disabled=true;
 try{
  if(!activePractice||!store)throw Error('請先開啟要補計稅額的練習');
  const result=replayWithCosts(s,state,makeTaxCorrectionModel(s));
  if(!result.ok){const c=result.conflict;saveStatus(`補計證交稅暫時無法完成：第 ${c.decisionNumber} 筆，${c.reason}。原紀錄未更改，未建立副本。${c.availableCash!==undefined?' 可用現金 '+feeMoney(c.availableCash):''}${c.requiredCash!==undefined?'；所需現金 '+feeMoney(c.requiredCash):''}`);return;}
  const {before,after}=result.comparison;
  if(!confirm(`補計證交稅，另存一份練習？
買賣手續費仍各0.1%，最低費與不取整方式不變；僅新增賣出證交稅 ${ratePercent(modelFor(result.s).sellTaxRate)}%（整元捨去）。
累計手續費：${feeMoney(before.fees)} → ${feeMoney(after.fees)}
累計證交稅：未計 → ${feeMoney(after.taxes)}
現金：${feeMoney(before.cash)} → ${feeMoney(after.cash)}
持有單位：${before.shares} → ${after.shares}
總資產：${feeMoney(before.wealth)} → ${feeMoney(after.wealth)}
原練習及決策會保留，不會覆蓋。`))return;
  result.s.taxRecalculation={kind:'add-sell-tax',sourcePracticeId:practiceMeta.id,sourcePracticeName:practiceMeta.name,sourceDatasetVersion:s.datasetVersion,sourceCostModel:modelFor(s),sourceDecisionCount:state.journal.length,recalculatedAt:new Date().toISOString()};
  const copy=makeSave(result.s,result.state,s.datasetVersion,draft(),new Date().toISOString()),suffix='（補計稅）';copy.practice={name:practiceMeta.name.slice(0,100-suffix.length)+suffix};
  store.write(copy,{replace:true});loadPractice(store.raw());showView('report');saveStatus('已另存補計證交稅的練習；原紀錄保持不變。');
 }catch(e){saveStatus('補計失敗：'+e.message+'。原紀錄保留。');}finally{button.disabled=false;}
});
