$('records-list').addEventListener('click',async e=>{const button=e.target.closest?.('[data-practice-action]');if(!button)return;const {practiceAction:action,id}=button.dataset;try{if(activePractice&&!['json','pdf'].includes(action)&&!persist())throw Error('目前草稿未保存，請先下載備份，再重試紀錄管理');const record=store.list({deleted:showDeleted}).find(r=>r.id===id);if(!record)throw Error('這份練習已變更，請重新整理');if(activePractice&&id===practiceMeta?.id&&['json','pdf'].includes(action))record.save={...makeSave(s,state,s.datasetVersion,draft(),createdAt),practice:practiceMeta};if(action==='open'){loadPractice(store.activate(id));showView(state.finished?'report':'trade');return;}if(action==='rename'){const name=globalThis.prompt('練習名稱（最多 100 字）',record.name);if(name===null)return;store.rename(id,name);if(id===practiceMeta?.id)practiceMeta={id,name:name.trim()};}else if(action==='trash'){if(!confirm('移到「已刪除」？可隨時還原，不會永久清除。'))return;store.trash(id);if(id===practiceMeta?.id){activePractice=false;refreshWorkspace();}}else if(action==='restore'){store.restore(id);}else if(action==='json'){download(JSON.stringify(record.save,null,2),'application/json',`practice-${id}.json`);}else if(action==='pdf'){button.disabled=true;const loaded=registry.restore(JSON.stringify(record.save));reconcileReveal(loaded.s,loaded.state,globalThis.localStorage);const bytes=await performancePdf(loaded.s,loaded.state,{...loaded.draft,practiceName:record.name,generatedAt:new Date().toISOString()});download(bytes,'application/pdf',reportFilename(loaded.s,loaded.state));}renderPractices();}catch(err){$('records-error').textContent=err.message;}finally{button.disabled=false;}});
