function newsTerms(n,raw=n){const text=String(n.title??'')+' '+String(n.body??'')+' '+String(raw.source??''),terms=[[/\bCPI\b|消費者物價/i,'CPI 是什麼？','消費者物價指數：追蹤一籃子商品與服務的價格變化，常用來描述通貨膨脹。它是統計資料，不直接預告股價。'],[/\bFOMC\b|聯準會|聯邦公開市場/i,'FOMC 是什麼？','美國聯邦公開市場委員會：討論貨幣政策、設定政策利率目標的決策機構。公告內容只是當時可取得的一項資訊。'],[/\bBLS\b|勞工統計|Bureau of Labor Statistics/i,'BLS 是什麼？','美國勞工統計局：發布就業與物價等官方統計。本練習盡量使用當時發布的數值，避免看到日後修訂。'],[/非農|就業人數/i,'就業數據怎麼讀？','就業統計描述勞動市場的變化。不同統計可能涵蓋不同人群或期間，不能只看一個數字判斷市場方向。']].filter(([pattern])=>pattern.test(text));return terms.length?'<details class="news-glossary"><summary>名詞說明</summary>'+terms.map(([,title,body])=>'<p><strong>'+title+'</strong><br>'+body+'</p>').join('')+'</details>':'';}
